const INSTRUMENTS=location.hash==='#instruments';
let seq=0,pending=new Map();
function api(op,args={}){return new Promise((resolve,reject)=>{const id=(INSTRUMENTS?'i':'')+String(++seq);pending.set(id,{resolve,reject});if(!window.webkit?.messageHandlers?.aster){pending.delete(id);reject(Error('Open Aster.app to connect to your local tools.'));return;}window.webkit.messageHandlers.aster.postMessage({id,op,args});});}
window.asterResponse=(id,value,error)=>{const p=pending.get(id);if(!p)return;pending.delete(id);error?p.reject(Error(error)):p.resolve(value);};
let S={ad2Status:null,ad2Capture:null,ad2Mode:'logic',ad2Span:0.05,ad2Channels:[0],ad2Trigger:{source:0,edge:'rise',level:1.5,position:10,mode:'auto'},ad2Range:50,ad2Measure:0,ad2View:null,ad2Cursor:{y1:null,y2:null,show:true,volts:false},ad2Cursors:[],ad2Active:0,ad2Chan:{0:{vdiv:1,center:0,invert:false},1:{vdiv:1,center:0,invert:false}},ad2Threshold:{mode:'mid',level:1.5},ad2Stats:null,ad2Last:null,ad2Snap:true,ad2Edges:[],ad2Running:false,ad2RunId:0,ad2Frames:0,project:null,files:new Map(),active:null,view:'files',panel:'output',busy:false,debug:'disconnected',location:{},values:{},previous:{},watches:[],breakpoints:[],stopwatch:null,diagnostics:[],output:'',debugOutput:'',serialOutput:'',memoryOutput:'',ports:[],serial:false,baud:19200,port:'',recent:[],device:{registers:[],configs:[],pins:[]},tools:[],details:null};
let toastTimer;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,error?10000:4200);}
function log(text){S.output=(S.output+text).slice(-300000);if(S.panel==='output')renderPanel();}
async function task(label,fn){if(S.busy){toast('An operation is already in progress.');return;}S.busy=true;$('#panelStatus').textContent=label;$('#buildStatus').textContent=label;$('#buildStatus').className='working';controls();try{return await fn();}catch(e){toast(e.message,true);$('#buildStatus').textContent='Needs attention';$('#buildStatus').className='bad';log('\n'+e.message+'\n');}finally{S.busy=false;$('#cancelBuild').hidden=true;$('#panelStatus').textContent=S.debug==='disconnected'?'Ready':S.debug==='running'?'Running':'Paused';controls();}}
function stopwatchClock(){const input=$('#stopwatchClock'),value=Number(input.value);if(!Number.isFinite(value)||value<0.001||value>64)throw Error('Enter an oscillator frequency from 0.001 to 64 MHz.');return value;}
function renderStopwatch(){
 const connected=S.debug!=='disconnected',sim=$('#debugTarget').value==='SIM',reading=connected&&sim?S.stopwatch:null;
 $('#resetStopwatch').disabled=!sim||S.debug!=='paused'||S.busy;
 $('#stopwatchClock').disabled=connected||S.busy;$('#stopwatchAccumulate').disabled=connected||S.busy;
 const clock=Number($('#stopwatchClock').value),projectClock=Number(S.project?.clockMHz);$('#stopwatchClockInfo').textContent=Number.isFinite(clock)&&clock>0?(clock/4).toLocaleString(undefined,{maximumFractionDigits:6})+' MHz instruction clock · '+(clock===projectClock?'default':'override'):'Enter a valid clock frequency.';
 if(reading?.available){const t=reading.seconds,scale=t<.000001?1e9:t<.001?1e6:t<1?1e3:1,unit=scale===1e9?'ns':scale===1e6?'µs':scale===1e3?'ms':'s';$('#stopwatchTime').textContent=reading.elapsedText||(t*scale).toLocaleString(undefined,{maximumFractionDigits:3})+' '+unit;$('#stopwatchCycles').textContent=BigInt(reading.cycles).toLocaleString()+' instruction cycles';}
 else{$('#stopwatchTime').textContent='—';$('#stopwatchCycles').textContent='— instruction cycles';}
 $('#stopwatchHint').textContent=!sim?'Cycle stopwatch is available in Simulator.':!connected?'Defaults to 16 MHz Fosc · change before starting.':S.debug==='running'?'Running · updates when paused.':reading?.error?'Stopwatch unavailable: '+reading.error:$('#stopwatchAccumulate').checked?'Since stopwatch reset · paused time is excluded.':'Last run · resets on Continue.';
}
function controls(){if(INSTRUMENTS)return;renderStopwatch();const has=!!S.project,debug=S.debug!=='disconnected',paused=S.debug==='paused';$('#buildButton').disabled=!has||S.busy||debug||S.project?.prebuilt;$('#cleanButton').disabled=$('#buildButton').disabled;$('#debugButton').disabled=!has||S.busy||debug;$('#programButton').disabled=!has||S.busy||debug;$('#saveButton').disabled=!S.active||S.busy||debug;$('#debugTarget').disabled=S.busy||debug;$('#configuration').disabled=S.busy||debug;$$('[data-debug]').forEach(b=>b.disabled=!debug||S.busy||(b.dataset.debug==='halt'?! (S.debug==='running'):b.dataset.debug!=='stop'&&!paused));$('#refreshRegisters').disabled=!paused||S.busy;$('#refreshStack').disabled=!paused||S.busy;$('#debugState').textContent=debug?S.debug.toUpperCase():'INACTIVE';$('#debugState').className='pill '+(debug?S.debug:'');if(S.active)E.readOnly(debug||S.files.get(S.active)?.readOnly||false);}
function panel(name){S.panel=name;$$('[data-panel]').forEach(el=>el.classList.toggle('active',el.dataset.panel===name));renderPanel();}
async function refreshProjectFiles(){
 const project=S.project;if(!project)return;
 const updated=await api('project');
 if(S.project!==project)return;
 S.project=updated;renderSidebar();
}
window.addEventListener('focus',()=>{if(S.project&&!S.busy&&S.debug==='disconnected')refreshProjectFiles().then(syncFromDisk).catch(e=>toast(e.message,true));});
// claude bridge: keep the ui in step with operations run from the bridge folder
window.asterHasUnsaved=()=>[...S.files.values()].some(f=>f.dirty);
function setBridge(b){S.bridge=b;const el=$('#bridgeStatus');if(el){el.hidden=!b?.enabled;el.title=b?.folder||'';}}
async function syncFromDisk(){if(!S.project)return;let changed=false;for(const [p,f] of S.files){if(f.readOnly)continue;let r;try{r=await api('read',{path:p});}catch{continue;}if(r.digest===f.digest)continue;if(f.dirty){toast(p.split('/').pop()+' changed on disk while it has unsaved edits here.',true);continue;}Object.assign(f,{content:r.content,digest:r.digest,encoding:r.encoding});changed=true;if(p===S.active&&!S.details)showFile(p);}if(changed){renderTabs();updateMarks();}}
async function bridgeEvent(d){const st=$('#buildStatus');if(d.phase==='start'){if(!S.busy){st.textContent='Claude · '+d.op+'…';st.className='working';}return;}
 try{if(!d.ok){if(!S.busy){st.textContent='Claude · '+d.op+' failed';st.className='bad';}return;}const v=d.value;
  if((d.op==='open'||d.op==='new')&&v){await loaded(v);}
  else if(d.op==='debugAction'&&d.args?.action==='stop'){S.debug='disconnected';S.values={};S.location={};S.stopwatch=null;$('#callStack').textContent='No active session';renderInspector();updateMarks();controls();}
  else if(['debugStart','debugAction','inspect','waitStop'].includes(d.op)&&v){applyInspection(v);controls();if(S.location.file&&S.files.has(S.location.file)){showFile(S.location.file);E.go(S.location.line||1);}if(d.op==='debugStart'&&S.debug==='paused'&&!S.busy)await refreshRegisters();}
  else if(d.op==='ad2Capture'&&v)ad2Received(v);
  else if(d.op==='ad2Run'&&v){S.ad2RunId=v.run;S.ad2Running=true;S.ad2Frames=0;ad2RunState();}
  else if(d.op==='ad2Stop'){S.ad2Running=false;ad2RunState();}
  else if(d.op==='resetStopwatch'&&v){S.stopwatch=v;renderStopwatch();}
  else if(d.op==='breakpoint'&&v){S.breakpoints=v.breakpoints;renderInspector();updateMarks();}
  else if(['addSource','configuration','project'].includes(d.op)&&v){S.project=v.project||v;renderSidebar();}
  if(!S.busy&&!['build','clean'].includes(d.op)){st.textContent='Claude · '+d.op;st.className='good';}
  if(S.debug==='disconnected')await syncFromDisk();
 }catch(e){toast(e.message,true);}}
function sourceFiles(){return (S.project?.files||[]).filter(f=>/\.(asm|s|c|h|inc|cpp)$/i.test(f.path));}
function fileIcon(path){const ext=path.split('.').pop().toLowerCase();return `<span class="file-icon ${esc(ext)}">${ext==='asm'||ext==='s'?'A':ext==='c'?'C':ext==='hex'?'⬡':ext==='xml'?'‹›':'≡'}</span>`;}
function renderSidebar(){const body=$('#sidebarBody');$('#sidebarTitle').textContent={files:'EXPLORER',search:'SEARCH',device:'DEVICE',config:'CONFIGURATION',reference:'REFERENCE'}[S.view];
 if(S.view==='files'){
  if(!S.project){body.innerHTML=`<div class="source-tag">Open your MPLAB project to begin. Your source files and build outputs will appear here.</div><div class="tree-heading">RECENT PROJECTS</div>${S.recent.slice(0,8).map((p,i)=>`<button class="file-row" data-recent="${i}">${icon('folder')}<span class="name">${esc(p.split('/').pop())}</span></button>`).join('')}`;body.querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>openProject(S.recent[+b.dataset.recent]));return;}
  const source=sourceFiles(),other=S.project.files.filter(f=>!source.includes(f));
  const rows=files=>files.map(f=>`<button class="file-row ${S.active===f.path?'active':''}" data-path="${esc(f.path)}" title="${esc(f.path)}">${fileIcon(f.path)}<span class="name">${esc(f.name)}</span>${S.files.get(f.path)?.dirty?'<small>●</small>':''}</button>`).join('');
  body.innerHTML=`<div class="tree-heading">⌄ &nbsp; ${esc(S.project.name.toUpperCase())}<span class="count">.X</span><button class="mini-icon" id="refreshFiles" title="Refresh project files" aria-label="Refresh project files">${icon('refresh')}</button></div><div class="tree-heading">⌄ &nbsp; Source files <span class="muted">${source.length}</span></div><button class="file-row" id="addSourceFile">＋ New source / header</button><button class="file-row" id="importSourceFile">Import starter into current tab</button><button class="file-row" id="exportSourceFile">Export current source…</button>${rows(source)}<div class="tree-separator"></div><div class="tree-heading">⌄ &nbsp; Project</div>${rows(other)}<div class="tree-separator"></div><div class="tree-heading">⌄ &nbsp; Build outputs <span class="count">${S.project.outputs.length}</span></div>${rows(S.project.outputs.filter(f=>/\.(hex|elf|map|lst|sym)$/.test(f.path)))}${S.project.outputs.length?'':'<div class="source-tag">Your HEX, ELF, and map files appear after a successful build.</div>'}`;
  $('#addSourceFile').onclick=addSourceFile;$('#importSourceFile').onclick=importSourceFile;$('#exportSourceFile').onclick=exportSourceFile;
  $('#refreshFiles').onclick=()=>task('Refreshing project files…',refreshProjectFiles);
  body.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>safeOpen(b.dataset.path));
 }else if(S.view==='search'){body.innerHTML='<div class="side-search"><input id="projectSearch" class="input small" placeholder="Search source files…" aria-label="Search source files"></div><div id="searchResults" class="source-tag" style="padding-top:16px">Search the current project’s source files.</div>';let timer;$('#projectSearch').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>projectSearch(e.target.value),250);};$('#projectSearch').focus();
 }else if(S.view==='device'){body.innerHTML=`<div class="tree-heading">PIC18F87K22</div><button class="file-row" id="showRegisters">${icon('chip')} Registers & bit fields</button><button class="file-row" id="showPins">${icon('sliders')} 80-pin package</button><div class="tree-separator"></div><div class="source-tag" style="padding-top:14px">Definitions from your installed<br>Microchip ${esc(S.device.pack)}.</div>`;$('#showRegisters').onclick=()=>deviceView();$('#showPins').onclick=()=>pinsView();
 }else if(S.view==='config'){body.innerHTML=`<div class="tree-heading">CONFIGURATION BITS</div><div class="source-tag">Select values from the device pack, then apply configuration directives to the current source.</div><button class="file-row" id="showConfigs">${icon('sliders')} Edit configuration</button>`;$('#showConfigs').onclick=configView;
 }else{body.innerHTML=`<div class="tree-heading">COURSE LIBRARY</div><div class="source-tag">Your labs and chip documentation, one click away.</div>`;}}
function renderTabs(){const tabs=$('#tabs');tabs.innerHTML=S.files.size?[...S.files].map(([p,f])=>`<button class="tab ${p===S.active&&!S.details?'active':''}" data-tab="${esc(p)}">${fileIcon(p)}<span class="name">${esc(p.split('/').pop())}</span>${f.dirty?'<span class="dirty"></span>':''}<span class="close-tab" data-close="${esc(p)}">×</span></button>`).join(''):'<span class="tab-placeholder">Workspace</span>';tabs.querySelectorAll('[data-tab]').forEach(b=>b.onclick=e=>{if(!e.target.closest('[data-close]'))showFile(b.dataset.tab);});tabs.querySelectorAll('[data-close]').forEach(b=>b.onclick=e=>{e.stopPropagation();closeFile(b.dataset.close);});}
async function safeOpen(path,line){try{await openFile(path,line);}catch(e){toast(e.message,true);}}
async function openFile(path,line){if(!S.files.has(path)){const file=await api('read',{path});S.files.set(path,{...file,dirty:false});}showFile(path);if(line)E.go(line);}
function showFile(path){S.active=path;S.details=null;const f=S.files.get(path);$('#welcome').hidden=true;$('#detail').hidden=true;$('#editor').hidden=false;E.open(path,f.content,f.readOnly||S.debug!=='disconnected');$('#breadcrumbs').innerHTML=`<span>${esc(S.project.name)}</span><span>›</span><span>Source</span><span>›</span><span>${esc(path.split('/').pop())}</span>`;$('#encodingStatus').textContent=f.encoding==='latin1'?'Latin-1':'UTF-8';$('#languageStatus').textContent=/\.(c|h|cpp)$/i.test(path)?'C / C++':'PIC18 Assembly';renderTabs();renderSidebar();updateMarks();controls();}
async function closeFile(path){const f=S.files.get(path);if(f.dirty&&!await api('confirm',{title:'Discard unsaved changes?',message:path.split('/').pop()+' has unsaved edits.',accept:'Discard Changes'}))return;S.files.delete(path);E.close(path);if(S.active===path){S.active=null;const next=[...S.files.keys()].pop();if(next)showFile(next);else welcome();}renderTabs();renderSidebar();controls();}
async function saveFile(path=S.active){if(!path)return;const f=S.files.get(path);if(!f.dirty)return;const r=await api('save',{path,content:f.content,digest:f.digest,encoding:f.encoding});f.digest=r.digest;f.dirty=false;renderTabs();renderSidebar();}
async function saveAll(){for(const [p,f] of S.files)if(f.dirty)await saveFile(p);}
async function canSwitch(){if(S.busy)return false;if(S.debug!=='disconnected'){toast('Stop the debug session before switching projects.');return false;}if([...S.files.values()].some(f=>f.dirty)){return await api('confirm',{title:'Open another project?',message:'Unsaved edits will be discarded. Cancel to save your work first.',accept:'Discard and Open'});}return true;}
async function openProject(path){if(!await canSwitch())return;await task('Opening project…',async()=>{if(!path)path=await api('chooseProject');if(!path)return;const p=await api('open',{path});await loaded(p);});}
async function loaded(p){S.project=p;S.watches=[...(p.watches||[])];S.files.clear();S.active=null;E.reset();S.view='files';S.diagnostics=[];S.output='';S.debugOutput='';S.memoryOutput='';S.breakpoints=[];S.stopwatch=null;S.location={};S.values={};S.debug='disconnected';$('#stopwatchClock').value=String(p.clockMHz??16);$('#problemCount').textContent='0';$('#projectTitle').innerHTML=esc(p.name)+' <span>⌄</span>';$('#configuration').innerHTML=p.configurations.map(c=>`<option ${c.name===p.configuration?'selected':''}>${esc(c.name)}</option>`).join('')||'<option>prebuilt</option>';$('#statusProject').textContent=p.name;$('#buildStatus').textContent='Project ready';$('#buildStatus').className='good';view('files');renderInspector();renderPanel();const first=sourceFiles()[0];if(first)await openFile(first.path);else welcome();}
function editableSource(){const file=S.files.get(S.active);if(!file||file.readOnly||S.debug!=='disconnected'||S.busy||!/\.(c|h|asm|s|inc)$/i.test(S.active)){toast('Open an editable source tab and stop debugging first.',true);return null;}return file;}
function addSourceFile(){if(!S.project||S.project.prebuilt||S.debug!=='disconnected'||S.busy){toast('Open a source project and stop debugging first.',true);return;}showModal('<h2>Add a source or header.</h2><p>The file will be included in this project. Use .c and .h for an XC8 C project.</p><input id="sourceName" class="input" placeholder="timers.c" aria-label="Filename"><div class="modal-actions"><button class="button" data-dismiss>Cancel</button><button id="createSource" class="button primary">Create file</button></div>');$('#createSource').onclick=()=>{const name=$('#sourceName').value.trim();$('#modal').close();task('Adding source file…',async()=>{const r=await api('addSource',{name});S.project=r.project;renderSidebar();await openFile(r.path);if(r.warning)toast(r.warning,true);});};$('#sourceName').focus();}
async function importSourceFile(){const file=editableSource(),path=S.active;if(!file)return;const picked=await api('chooseSource');if(!picked)return;if(S.active!==path)return;const ext=n=>n.split('.').pop().toLowerCase();if(ext(picked.name)!==ext(path)){toast('Choose a starter with the same file type as the current tab.',true);return;}if(file.content.trim()&&!await api('confirm',{title:'Replace the current editor contents?',message:'Copy '+picked.name+' into '+path.split('/').pop()+'? You can undo this before saving.',accept:'Import'}))return;showFile(path);E.replace(picked.content);toast('Starter imported. Review, then save and build.');}
function exportSourceFile(){const file=editableSource();if(!file)return;task('Exporting source…',async()=>{await api('exportText',{name:S.active.split('/').pop(),content:file.content});});}
async function newProject(){if(!await canSwitch())return;showModal(`<h2>Start a PIC18 project.</h2><p>Start with a blank file or choose an example. All projects open in MPLAB X 6.20.</p><button class="ref-card" id="newBlank">${icon('files')}<div><strong>Blank project</strong><small>An empty main.asm, ready for your own code.</small></div>${icon('arrow')}</button><button class="ref-card" id="newC">${icon('files')}<div><strong>XC8 C project</strong><small>A compilable main.c with the XC8 toolchain, ready for your timer ISR.</small></div>${icon('arrow')}</button><button class="ref-card" id="newBasic">${icon('files')}<div><strong>Assembly starter</strong><small>A simple counter for learning the editor and debugger.</small></div>${icon('arrow')}</button><button class="ref-card" id="newInterrupt">${icon('chip')}<div><strong>Interrupt bench</strong><small>INT0 on RB0, an ISR, and a counter you can watch.</small></div>${icon('arrow')}</button><div class="modal-actions"><button class="button" data-dismiss>Cancel</button></div>`);const create=template=>{ $('#modal').close();task('Creating project…',async()=>{const path=await api('chooseNew');if(!path)return;await loaded(await api('new',{path,template}));if(template==='interrupt')addWatch('irq_count');toast(template==='blank'?'Blank project created. Write your code in main.asm.':template==='c'?'XC8 C project created. Build it or start the simulator.':'Project created. Build it or start the simulator.');});};$('#newBlank').onclick=()=>create('blank');$('#newC').onclick=()=>create('c');$('#newBasic').onclick=()=>create('basic');$('#newInterrupt').onclick=()=>create('interrupt');}

function welcome(){S.details=null;$('#editor').hidden=true;$('#detail').hidden=true;$('#welcome').hidden=false;$('#breadcrumbs').innerHTML='<span>Aster</span><span>›</span><span>Getting started</span>';$('#welcome').innerHTML=`<div class="welcome-inner"><div class="eyebrow"><span class="tiny-dot"></span> YOUR BENCH, REIMAGINED</div><h1>A little closer<br>to the <span>hardware.</span></h1><p class="intro">Write, build, and debug C or assembly.<br>A focused workspace for your avionics labs.</p><div class="welcome-actions"><button class="button primary" id="welcomeOpen">${icon('folder')} Open project</button><button class="button" id="welcomeNew">＋ New project</button></div><div class="section-label">PICK UP WHERE YOU LEFT OFF <span>${S.recent.length} PROJECTS</span></div>${S.recent.slice(0,3).map((p,i)=>`<button class="recent-card" data-recent="${i}">${icon('folder')}<div><strong>${esc(p.split('/').pop())}</strong><small>${esc(p.replace(/^\/Users\/[^/]+/,'~'))}</small></div><span class="arrow">↗</span></button>`).join('')}<div class="welcome-meta"><span>${icon('check')} MPLAB project compatible</span><span>${icon('chip')} PIC18F87K22</span><span>${icon('shield')} Runs locally</span></div></div>`;$('#welcomeOpen').onclick=()=>openProject();$('#welcomeNew').onclick=newProject;$('#welcome').querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>openProject(S.recent[+b.dataset.recent]));renderTabs();}
function view(name){S.view=name;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));renderSidebar();if(name==='device')deviceView();if(name==='config')configView();if(name==='reference')referenceView();if(name==='files'||name==='search'){if(S.active)showFile(S.active);else welcome();}}
function detail(title,html){S.details=title;$('#editor').hidden=true;$('#welcome').hidden=true;$('#detail').hidden=false;$('#detail').innerHTML=`<div class="detail-inner">${html}</div>`;$('#breadcrumbs').innerHTML=`<span>PIC18F87K22</span><span>›</span><span>${esc(title)}</span>`;renderTabs();}
function deviceView(){detail('Device & registers',`<div class="eyebrow">DEVICE REFERENCE</div><h2>PIC18F87K22</h2><p>The registers, fields, and addresses of your chip. Add any register to Watches to inspect it during a debug session.</p><div class="chip-stat-grid"><div class="chip-stat"><strong>128 KB</strong><small>Program flash</small></div><div class="chip-stat"><strong>3,896 B</strong><small>Data RAM</small></div><div class="chip-stat"><strong>1 KB</strong><small>EEPROM</small></div></div><div class="filter-row"><input id="registerFilter" class="input" placeholder="Find a register or bit field…" aria-label="Find a register"></div><table class="detail-table"><thead><tr><th>REGISTER</th><th>ADDRESS</th><th>BIT FIELDS</th><th></th></tr></thead><tbody id="registerTable"></tbody></table>`);function table(q=''){$('#registerTable').innerHTML=S.device.registers.filter(r=>(r.name+' '+r.bits.join(' ')).toLowerCase().includes(q.toLowerCase())).map(r=>`<tr><td>${esc(r.name)}</td><td style="font-family:var(--mono)">${esc(r.address)}</td><td>${esc(r.bits.join(' · '))}</td><td><button class="text-button" data-watch="${esc(r.name)}">+ Watch</button></td></tr>`).join('');$$('[data-watch]').forEach(b=>b.onclick=()=>addWatch(b.dataset.watch));}table();$('#registerFilter').oninput=e=>table(e.target.value);}
function pinsView(){detail('80-pin package',`<div class="eyebrow">PACKAGE REFERENCE</div><h2>Every pin, in one place.</h2><p>Device-pack pin order and multiplexed signals. Check the EasyPIC board schematic for header routing and jumper positions.</p><button id="openBoardManual" class="button">${icon('book')} Open board manual</button><div class="pins-grid">${S.device.pins.map((p,i)=>`<div class="pin-item"><b>${i+1}</b><span>${esc(p.signals.map(s=>s.cname||s.name||Object.values(s).join(' ')).join(' / '))}</span></div>`).join('')}</div>`);$('#openBoardManual').onclick=()=>api('openDoc',{key:'board'}).catch(e=>toast(e.message,true));}
function configView(){const file=S.active?S.files.get(S.active):null;const isC=/\.c$/i.test(S.active||'');const directive=isC?'#pragma config':'CONFIG';const selected=AsterConfig.read(file?.content||'',S.device.configs),removed=new Set();detail('Configuration bits',`<div class="eyebrow">DEVICE CONFIGURATION</div><h2>Make the settings explicit.</h2><p>These options come directly from your PIC18F87K22 device pack. Only selected fields are emitted. Applying updates the active source file with assembly CONFIG directives or XC8 C pragmas.</p><div class="inline-notice">Editing ${file?esc(S.active.split('/').pop()):'no source file'}. Configuration changes take effect after building and programming. Review clock and watchdog settings against your lab.</div><div class="filter-row"><input id="configFilter" class="input" placeholder="Filter configuration fields…" aria-label="Filter configuration fields"><button class="button primary" id="applyConfig">Apply to source</button></div><textarea id="configCode" class="input config-output" readonly aria-label="Generated configuration source"></textarea><table class="detail-table"><thead><tr><th>FIELD</th><th>SETTING</th><th>DESCRIPTION</th></tr></thead><tbody id="configTable"></tbody></table>`);
 function output(){$('#configCode').value=Object.entries(selected).map(([k,v])=>`${directive} ${k} = ${v}`).join('\n');}
 function table(q=''){$('#configTable').innerHTML=S.device.configs.filter(c=>(c.name+' '+c.description).toLowerCase().includes(q.toLowerCase())).map((c)=>`<tr><td title="${esc(c.register)}">${esc(c.name)}</td><td><select data-config="${esc(c.name)}" aria-label="${esc(c.name)}"><option value="">Unspecified</option>${c.options.map(o=>`<option value="${esc(o.name)}" ${selected[c.name]===o.name?'selected':''}>${esc(o.name)}</option>`).join('')}</select></td><td>${esc(c.description)}</td></tr>`).join('');$$('[data-config]').forEach(el=>el.onchange=()=>{if(el.value){selected[el.dataset.config]=el.value;removed.delete(el.dataset.config);}else{delete selected[el.dataset.config];removed.add(el.dataset.config);}output();});}table();output();$('#configFilter').oninput=e=>table(e.target.value);$('#applyConfig').disabled=!file||file.readOnly||S.debug!=='disconnected'||!(/\.(asm|s|c)$/i.test(S.active||''));$('#applyConfig').onclick=()=>{const content=AsterConfig.apply(file.content,selected,removed,S.device.configs,directive);showFile(S.active);E.replace(content);toast('Configuration updated in the editor. Save and build to apply.');};}
function referenceView(){const docs=[['lab1','Lab 1 · Development board','Board setup, programming, and serial communication'],['lab2','Lab 2 · Development environment','Simulation, breakpoints, registers, and memory'],['lab3','Lab 3 · Basic input and output','Digital I/O and your lab workflow'],['lab4','Lab 4 · Timers, LCD and servo','Lab instructions and requirements'],['lab5','Lab 5 · Timers, interrupts and CCP','Assembly and C requirements, timing measurements'],['introC','Introduction to C','Course guide to C syntax, types, pointers, and volatile'],['xc8Guide','XC8 C compiler manual','Interrupts, configuration pragmas, and compiler options'],['embeddedC','XC8 guide for embedded engineers','Worked examples for PIC C development'],['encoders','NI encoder tutorial','Quadrature signals and decoding'],['rpg','Bourns 3315 encoder','Pinout, resolution, and contact bounce'],['peatmanLCD','Peatman · LCD','LCD timing, strings, and display routines'],['peatmanRPG','Peatman · Rotary pulse generators','Polling, direction, and transition decoding'],['datasheet','PIC18F87K22 datasheet','The complete chip reference'],['board','EasyPIC PRO v7 manual','Pins, headers, jumpers, and peripherals'],['assembler','PIC assembler guide · XC8 2.46','Directives, linker options, and output files']];detail('Course references',`<div class="eyebrow">AT YOUR WORKBENCH</div><h2>The right reference, nearby.</h2><p>Documents open in your PDF reader. Aster checks beside your project and in Downloads; if needed, locate a PDF once to remember its folder.</p>${docs.map(([k,n,d])=>`<button class="ref-card" data-doc="${k}">${icon('book')}<div><strong>${n}</strong><small>${d}</small></div>${icon('arrow')}</button>`).join('')}`);$$('[data-doc]').forEach(b=>b.onclick=()=>api('openDoc',{key:b.dataset.doc}).catch(e=>toast(e.message,true)));}
async function projectSearch(query){if(!query||!S.project)return;const results=[];for(const f of sourceFiles()){let content=S.files.get(f.path)?.content;if(content===undefined){try{content=(await api('read',{path:f.path})).content;}catch{continue;}}content.split('\n').forEach((text,i)=>{if(text.toLowerCase().includes(query.toLowerCase())&&results.length<150)results.push({path:f.path,name:f.name,line:i+1,text});});}const target=$('#searchResults');if(!target||$('#projectSearch')?.value!==query)return;target.className='';target.innerHTML=results.length?results.map((r,i)=>`<button class="search-result" data-result="${i}"><strong>${esc(r.name)} : ${r.line}</strong><small>${esc(r.text.trim())}</small></button>`).join(''):'<div class="source-tag" style="padding-top:16px">No matches.</div>';target.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const r=results[+b.dataset.result];safeOpen(r.path,r.line);});}
